class Solution {
    int n;
    vector<int> dp;

    int solve(int mask) {
        if (dp[mask] != -1) return dp[mask];
        int pos = __builtin_popcount(mask) + 1;
        int res = 0;
        for (int j = 1; j <= n; j++) {
            if (mask & (1 << (j - 1))) continue;
            if (j % pos == 0 || pos % j == 0) {
                res += solve(mask | (1 << (j - 1)));
            }
        }
        dp[mask] = res;
        return res;
    }

public:
    int countArrangement(int n) {
        this->n = n;
        dp.assign(1 << n, -1);
        dp[(1 << n) - 1] = 1;
        return solve(0);
    }
};
